+/**
+ * Remove executable content from untrusted SVG before parsing/rendering.
+ * Scratch project assets are untrusted input and must not be able to inject
+ * scriptable HTML/SVG content into the DOM.
+ * @param {string} svgString raw SVG text
+ * @returns {string} sanitized SVG text
+ */
+const sanitizeSvgString = function (svgString) {
+    if (typeof svgString !== 'string' || svgString.length === 0) {
+        return svgString;
+    }
+
+    return svgString
+        // Remove scriptable elements.
+        .replace(/<\s*(script|foreignObject)\b[\s\S]*?<\s*\/\s*\1\s*>/gi, '')
+        // Remove inline event handlers such as onload= / onclick=
+        .replace(/\s+on[a-zA-Z]+\s*=\s*(['"]).*?\1/g, '')
