+pub fn verify_signed_json(body: &str, signature_hex: &str, pem_chain: &str) -> Result<()> {
+    let certs = parse_pem_chain(pem_chain)?;
+    let leaf = certs.first().ok_or(Error::InvalidCertificateChain)?;
+
+    let spki = leaf.public_key();
+    let verifying_key = VerifyingKey::from_sec1_bytes(spki.subject_public_key.data)
+        .map_err(|_| Error::InvalidSignature)?;
+
+    let sig = hex::decode(signature_hex).map_err(|_| Error::InvalidSignature)?;
+    let sig = Signature::from_der(&sig)
+        .or_else(|_| Signature::from_bytes((&sig).into()))
+        .map_err(|_| Error::InvalidSignature)?;
+
+    verifying_key
+        .verify(body.as_bytes(), &sig)
+        .map_err(|_| Error::InvalidSignature)?;
+
+    // Ensure the leaf is an SGX TCB/QE collateral signing cert.
+    let has_digital_signature = leaf
+        .tbs_certificate
+        .extensions()
+        .iter()
+        .find_map(|ext| match &ext.parsed_extension() {
+            ParsedExtension::KeyUsage(ku) => Some(ku.digital_signature()),
+            _ => None,
+        })
+        .unwrap_or(false);
+
+    if !has_digital_signature {
+        return Err(Error::InvalidCertificateChain);
+    }
+
+    Ok(())
+}
