+<?php
+
+namespace MongoDB\Subscriber;
+
+use MongoDB\Driver\Monitoring\CommandFailedEvent;
+use MongoDB\Driver\Monitoring\CommandStartedEvent;
+use MongoDB\Driver\Monitoring\CommandSubscriber;
+use MongoDB\Driver\Monitoring\CommandSucceededEvent;
+
+/**
+ * Command subscriber that suppresses sensitive authentication-related commands.
+ *
+ * @internal
+ */
+final class LoggingCommandSubscriber implements CommandSubscriber
+{
+    private $subscriber;
+
+    public function __construct(CommandSubscriber $subscriber)
+    {
+        $this->subscriber = $subscriber;
+    }
+
+    public function commandStarted(CommandStartedEvent $event)
+    {
+        if (\MongoDB\isSensitiveCommand($event->getCommandName())) {
+            return;
+        }
+
+        $this->subscriber->commandStarted($event);
+    }
+
+    public function commandSucceeded(CommandSucceededEvent $event) { $this->subscriber->commandSucceeded($event); }
+
+    public function commandFailed(CommandFailedEvent $event) { $this->subscriber->commandFailed($event); }
+}

